// Client API mobile.
// ⚠️ En natif, "localhost" = le téléphone, PAS ton Mac. Mets l'IP LAN de ta
// machine (téléphone + Mac sur le même Wi-Fi), ou l'URL de prod.
//   macOS : ipconfig getifaddr en0   →  ex. http://192.168.1.20:3000
import { Platform } from 'react-native';
import * as SecureStore from 'expo-secure-store';

// Résolution de l'URL de l'API :
//  1. EXPO_PUBLIC_API_BASE (défini au build) l'emporte toujours → prod / natif.
//  2. Web servi par Express (same-origin) → '' : les requêtes partent en /api/…
//  3. Web en dev (expo start --web sur localhost) → localhost:3000.
//  4. Natif en dev → IP LAN du Mac (`ipconfig getifaddr en0`).
const ENV_BASE = process.env.EXPO_PUBLIC_API_BASE;
const isLocalhostWeb =
  Platform.OS === 'web' &&
  typeof location !== 'undefined' &&
  (location.hostname === 'localhost' || location.hostname === '127.0.0.1');

export const API_BASE =
  ENV_BASE != null && ENV_BASE !== ''
    ? ENV_BASE
    : Platform.OS === 'web'
      ? (isLocalhostWeb ? 'http://localhost:3000' : '') // same-origin en prod
      : 'https://app.jiayou.fr'; // natif : défaut = prod (OTA-safe). Pour du dev
        // local, définis EXPO_PUBLIC_API_BASE (ex: http://192.168.1.3:3000).

const TOKEN_KEY = 'jiayou_token';
const isWeb = Platform.OS === 'web';

// Stockage du token : SecureStore en natif, localStorage sur web
// (SecureStore n'existe pas dans le navigateur).
export async function getToken() {
  if (isWeb) return typeof localStorage !== 'undefined' ? localStorage.getItem(TOKEN_KEY) : null;
  return SecureStore.getItemAsync(TOKEN_KEY);
}

export async function setToken(token) {
  if (isWeb) {
    if (typeof localStorage === 'undefined') return;
    if (token) localStorage.setItem(TOKEN_KEY, token);
    else localStorage.removeItem(TOKEN_KEY);
    return;
  }
  if (token) await SecureStore.setItemAsync(TOKEN_KEY, token);
  else await SecureStore.deleteItemAsync(TOKEN_KEY);
}

// Code de parrainage capté depuis l'URL (?ref=) à la première visite. On le
// PERSISTE car l'inscription passe par un redirect Google OAuth qui efface la
// query : il faut le retrouver au moment de l'onboarding pour créditer le
// parrain. Nettoyé une fois l'onboarding terminé.
const REF_KEY = 'jiayou_pending_ref';

export async function getPendingRef() {
  try {
    if (isWeb) return typeof localStorage !== 'undefined' ? localStorage.getItem(REF_KEY) : null;
    return await SecureStore.getItemAsync(REF_KEY);
  } catch { return null; }
}

export async function setPendingRef(code) {
  try {
    if (isWeb) { if (typeof localStorage !== 'undefined') localStorage.setItem(REF_KEY, code); return; }
    await SecureStore.setItemAsync(REF_KEY, code);
  } catch { /* noop */ }
}

export async function clearPendingRef() {
  try {
    if (isWeb) { if (typeof localStorage !== 'undefined') localStorage.removeItem(REF_KEY); return; }
    await SecureStore.deleteItemAsync(REF_KEY);
  } catch { /* noop */ }
}

// Paywall global : les réponses d'erreur des limites du plan gratuit portent
// `upgradeRequired: true` (+ `feature`). On notifie un handler unique enregistré
// par App.js → une popup « Go Premium » s'affiche à la racine, AU-DESSUS de toutes
// les autres popups (le message d'erreur inline était sinon caché derrière elles).
let upgradeHandler = null;
export function setUpgradeHandler(fn) { upgradeHandler = fn; }
// Ouvre le paywall à la demande (fonctionnalité premium touchée côté client, sans
// même appeler l'API — ex. entrer en mode multi-sélection sans être premium).
export function notifyUpgrade(feature = 'default', data = {}) {
  if (upgradeHandler) { try { upgradeHandler(feature, data); } catch { /* noop */ } }
}

// Solde insuffisant (402 `insufficient`) : il n'existe pas d'achat de pièces →
// on affiche une popup « comment gagner des pièces » (mêmes raisons que le paywall).
let coinsHandler = null;
export function setCoinsHandler(fn) { coinsHandler = fn; }
// Déclenche la popup « comment gagner des pièces » à la demande (ex. bouton
// d'achat pressé sans fonds suffisants, sans même appeler l'API).
export function notifyNeedCoins(data = {}) {
  if (coinsHandler) { try { coinsHandler(data); } catch { /* noop */ } }
}

// Token mort : une requête AUTHENTIFIÉE qui renvoie 401 = token expiré (TTL 30 j)
// ou invalide (secret serveur changé). On purge le token et on notifie App.js pour
// forcer le retour à l'écran de login — sinon "session fantôme" : `authed` reste
// vrai (un token existe en storage) mais tous les appels échouent, sans issue.
// N.B. : un échec RÉSEAU fait throw `fetch` AVANT ce bloc → la session est
// préservée (app hors-ligne reste utilisable). Seul un vrai 401 déconnecte.
let unauthorizedHandler = null;
export function setUnauthorizedHandler(fn) { unauthorizedHandler = fn; }

// Timeout dur par requête : sans lui, `fetch` peut pendre indéfiniment sur un
// réseau lent/instable (ex. Chine) → l'app paraît figée. On coupe à 15 s.
const REQUEST_TIMEOUT_MS = 15000;

// Normalise un échec de couche réseau (offline / timeout / abort) en une erreur
// propre : plus de message brut Expo (« …offline. (at ExpoModulesCore/Promise.swift:56) »)
// affiché en rouge. `isOffline` permet aux écrans d'afficher un empty state dédié ;
// ErrorRetry ignore de toute façon `message` et montre un texte localisé générique.
function offlineError(orig) {
  const err = new Error('No internet connection. Please check your network and try again.');
  err.isOffline = true;
  err.original = orig;
  return err;
}

async function request(path, { method = 'GET', body, auth = true } = {}) {
  const headers = { 'Content-Type': 'application/json' };
  if (auth) {
    const token = await getToken();
    if (token) headers.Authorization = `Bearer ${token}`;
  }
  // Un fetch borné par un AbortController (timeout). `finally` nettoie le timer.
  const doFetch = async () => {
    const controller = new AbortController();
    const timer = setTimeout(() => controller.abort(), REQUEST_TIMEOUT_MS);
    try {
      return await fetch(`${API_BASE}${path}`, {
        method,
        headers,
        body: body ? JSON.stringify(body) : undefined,
        signal: controller.signal,
      });
    } finally {
      clearTimeout(timer);
    }
  };
  let res;
  try {
    res = await doFetch();
  } catch (e) {
    // Échec réseau / timeout : UN seul réessai, et UNIQUEMENT pour les GET
    // (idempotents). On ne rejoue jamais un POST/PUT/DELETE → pas de double envoi
    // (achat, création de pack, envoi de coins…).
    if (method === 'GET') {
      try { res = await doFetch(); } catch (e2) { throw offlineError(e2); }
    } else throw offlineError(e);
  }
  const data = await res.json().catch(() => ({}));
  if (!res.ok) {
    // Token mort sur une requête authentifiée → purge + logout global. Les
    // endpoints de login/register passent `auth:false` : leurs 401 (mauvais
    // identifiants) ne déclenchent donc PAS de déconnexion.
    if (res.status === 401 && auth) {
      try { await setToken(null); } catch { /* noop */ }
      if (unauthorizedHandler) { try { unauthorizedHandler(); } catch { /* noop */ } }
    }
    // Limite du plan gratuit → paywall global (avant de throw, pour qu'il
    // s'affiche même si l'appelant avale l'erreur silencieusement).
    if (data && data.upgradeRequired && upgradeHandler) {
      try { upgradeHandler(data.feature || 'default', data); } catch { /* noop */ }
    } else if (data && data.insufficient && coinsHandler) {
      try { coinsHandler(data); } catch { /* noop */ }
    }
    const err = new Error(data.error || `HTTP ${res.status}`);
    err.status = res.status;
    err.data = data; // ex. { missing: [...] } pour la création de pack
    throw err;
  }
  return data;
}

